CREATE TABLE roles (id VARCHAR(30) PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE permissions (id VARCHAR(80) PRIMARY KEY);
CREATE TABLE role_permissions (role_id VARCHAR(30) NOT NULL, permission_id VARCHAR(80) NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id CHAR(36) PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(160) NOT NULL, email VARCHAR(254) UNIQUE NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, password_hash VARCHAR(255) NOT NULL, role_id VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, must_change_password BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id));
CREATE TABLE settings (id TINYINT PRIMARY KEY, company_name VARCHAR(160) NOT NULL, timezone VARCHAR(80) NOT NULL);
CREATE TABLE customers (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, organization VARCHAR(180) NOT NULL DEFAULT '', email VARCHAR(254) NULL, phone VARCHAR(40) NOT NULL DEFAULT '', contact_verified BOOLEAN NOT NULL DEFAULT FALSE, company_info TEXT, owner_id CHAR(36) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Active', notes TEXT, confidential BOOLEAN NOT NULL DEFAULT FALSE, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), INDEX(status,archived_at), INDEX(owner_id));
CREATE TABLE leads (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, organization VARCHAR(180) NOT NULL DEFAULT '', email VARCHAR(254) NULL, phone VARCHAR(40) NOT NULL DEFAULT '', contact_verified BOOLEAN NOT NULL DEFAULT FALSE, owner_id CHAR(36) NOT NULL, source VARCHAR(120) NOT NULL DEFAULT '', status VARCHAR(30) NOT NULL DEFAULT 'New', priority VARCHAR(20) NOT NULL DEFAULT 'Medium', follow_up_date DATE NULL, value DECIMAL(15,2) NOT NULL DEFAULT 0, currency CHAR(3) NOT NULL DEFAULT 'INR', notes TEXT, confidential BOOLEAN NOT NULL DEFAULT FALSE, converted_customer_id CHAR(36) NULL, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(converted_customer_id) REFERENCES customers(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), INDEX(status,archived_at), INDEX(owner_id), INDEX(follow_up_date));
CREATE TABLE projects (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT, owner_id CHAR(36) NOT NULL, customer_id CHAR(36) NULL, start_date DATE NULL, due_date DATE NULL, priority VARCHAR(20) NOT NULL DEFAULT 'Medium', status VARCHAR(30) NOT NULL DEFAULT 'Planning', progress TINYINT UNSIGNED NOT NULL DEFAULT 0, notes TEXT, confidential BOOLEAN NOT NULL DEFAULT FALSE, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), CHECK(progress<=100), INDEX(status,archived_at), INDEX(owner_id), INDEX(due_date));
CREATE TABLE project_members (project_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, PRIMARY KEY(project_id,user_id), FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE tasks (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, description TEXT, assignee_id CHAR(36) NOT NULL, project_id CHAR(36) NULL, priority VARCHAR(20) NOT NULL DEFAULT 'Medium', status VARCHAR(30) NOT NULL DEFAULT 'To Do', progress TINYINT UNSIGNED NOT NULL DEFAULT 0, start_date DATE NULL, due_date DATE NULL, completed_at DATETIME NULL, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(assignee_id) REFERENCES users(id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), CHECK(progress<=100), INDEX(assignee_id,status), INDEX(project_id), INDEX(due_date,status));
CREATE TABLE meetings (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, agenda TEXT, organizer_id CHAR(36) NOT NULL, customer_id CHAR(36) NULL, project_id CHAR(36) NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, notes TEXT, action_items TEXT, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(organizer_id) REFERENCES users(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), INDEX(starts_at));
CREATE TABLE meeting_participants (meeting_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, PRIMARY KEY(meeting_id,user_id), FOREIGN KEY(meeting_id) REFERENCES meetings(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE announcements (id CHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, message TEXT NOT NULL, audience VARCHAR(30) NOT NULL DEFAULT 'all', pinned BOOLEAN NOT NULL DEFAULT FALSE, archived_at DATETIME NULL, created_by CHAR(36) NOT NULL, updated_by CHAR(36) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), INDEX(audience,pinned));
CREATE TABLE task_comments (id CHAR(36) PRIMARY KEY, task_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(task_id) REFERENCES tasks(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(task_id));
CREATE TABLE record_comments (id CHAR(36) PRIMARY KEY, module VARCHAR(30) NOT NULL, record_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(module,record_id));
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, message VARCHAR(255) NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id,read_at));
CREATE TABLE activity_logs (id CHAR(36) PRIMARY KEY, actor_id CHAR(36) NULL, action VARCHAR(80) NOT NULL, module VARCHAR(30) NOT NULL, record_id CHAR(36) NULL, summary VARCHAR(255) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(actor_id) REFERENCES users(id), INDEX(created_at), INDEX(module,record_id), INDEX(actor_id));
